function referenceDetailConfirmationStepTimeoutMs() {
  var configured = Number(globalThis && globalThis.__SZ_REFERENCE_DETAIL_CONFIRM_TIMEOUT_MS__);
  return Number.isFinite(configured) && configured >= 25
    ? Math.min(60000, Math.floor(configured))
    : 15000;
}

function referenceDetailBoundedConfirmationStep(promise, stage) {
  var timeoutMs = referenceDetailConfirmationStepTimeoutMs();
  return new Promise(function (resolve, reject) {
    var settled = false;
    var timer = setTimeout(function () {
      if (settled) return;
      settled = true;
      reject(Object.assign(new Error('后台' + stage + '超时，已自动解锁工作台，可直接重试；若连续超时再刷新扩展。'), {
        code: 'CONFIRMATION_STEP_TIMEOUT',
        stage: stage,
        timeoutMs: timeoutMs,
        transport: true
      }));
    }, timeoutMs);
    Promise.resolve(promise).then(function (value) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(value);
    }, function (error) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      reject(error);
    });
  });
}

